  opportunistic = {'k': 2.0, 'm': 2.0, 'note': '⚠️ HIỆN INERT, KHÔNG PHẢI DO CẤU HÌNH: injector đo turnover phiên qua DNSE latest_trade.totalVolumeTraded, field này ở đơn vị 10 CP (đo [REDACTED]: TV1 trả 3.950 trong khi KL thật 39.500; DRI 101.160 vs 1.011.600 — đúng 10× ở cả hai) ⇒ turnover bị khai THIẾU 10× ⇒ điều kiện turnover ≥ k×adv_ref gần như không bao giờ đúng. Hệ quả CHỈ là mất phần boost ×2 (an toàn một chiều: mua ÍT hơn, không bao giờ nhiều hơn) và với TV1 thì trần cap vốn không bind nên KHÔNG đổi lệnh nào. Bug riêng, đã ghi bus job Taylor_20260812_161457, sửa cần tự xác minh đơn vị + quant-skeptic riêng.'}
  price_band= {'resting_limit': 19900, 'no_chase_ceiling': 20000, 'max_no_chase_ceiling': 25000, 'floor': None, 'floor_note': 'Không có sàn cắt-lỗ theo giá: downside che bởi tài sản hydro (Sông Bung 5) dưới giá M&A. Rẻ hơn = tốt hơn, trừ khi vi phạm hard_expiry phi-giá.', 'band_note': 'resting_limit/no_chase_ceiling là band CỐ ĐỊNH gốc (duyệt [REDACTED]) — nay chỉ còn vai trò (a) fail-safe khi trần động không kích hoạt được, (b) giữ TỈ LỆ resting/ceiling = 0,995 để trần động kéo resting theo. max_no_chase_ceiling = 25.000đ là trần TUYỆT ĐỐI user duyệt [REDACTED] (vùng chấp nhận 23.000–25.000đ, chọn cận trên để có dư địa); trần động KHÔNG BAO GIỜ vượt số này.'}
  dynamic_ceiling= {'enabled': True, 'tau': 0.03, 'sessions': 5, 'note': 'P1 (commit ec0120c): trần = min(mean(giá đóng 5 phiên ĐÃ HOÀN TẤT) × (1+τ), max_no_chase_ceiling), resting kéo theo cùng tỉ lệ. τ=3% từ nghiên cứu Taylor_20260812_091343 (N=1.840 phiên-mã, rổ 23 mã ADV20 200-2.500tr): fill 0,627→0,783, %phiên trắng tay 22,4%→6,1%, giá trả thêm +0,77pp. Anchor chỉ lấy phiên đã đóng (loại nến hôm nay đang chạy). Mọi điều kiện thiếu/rác ⇒ fail-safe về band cố định, không có đường fail-OPEN.'}
  hard_expiry= {'manual_only': True, 'halted': False, 'halted_reason': None, 'conditions': ['Kiểm toán FY2026 ra ý kiến NGOẠI TRỪ / TỪ CHỐI (disclaimer) / TRÁI NGƯỢC (adverse).', 'TV1 bị ĐÌNH CHỈ hoặc HẠN CHẾ giao dịch (tiền lệ DGC).'], 'automatable': 'KHÔNG — cả 2 điều kiện là tin pháp lý/kiểm toán tương lai, không đọc được tự động đáng tin. NGƯỜI xác nhận rồi set halted=true + halted_reason. Winston theo dõi corp-action/tin; khi kích hoạt → cập nhật state này (engine tự dừng gom ngay phiên kế). ĐÂY LÀ CÔNG TẮC DỪNG DUY NHẤT của chương trình tỷ trọng — nó không tự đóng khi đủ hàng.'}
