cd /home/trido/thanhdt/WorkingClaude
for tz in "DEFAULT" "UNSET" "America/New_York" "UTC"; do
  case $tz in
    DEFAULT) out=$(timeout 600 python3 discretionary_target_pct_selfcheck.py 2>&1 | tail -1);;
    UNSET)   out=$(env -u TZ timeout 600 python3 discretionary_target_pct_selfcheck.py 2>&1 | tail -1);;
    *)       out=$(TZ=$tz timeout 600 python3 discretionary_target_pct_selfcheck.py 2>&1 | tail -1);;
  esac
  echo "TZ=$tz -> $out"
done
